      p_source         => 
'DECLARE
    v_capacidad number;
BEGIN
    -- Comprobar capacidad
    select nvl(equ_capacidad,emp_capacidad) into v_capacidad
    from equipos, empresas
    where equ_emp = emp_id
        and equ_licencia = :licencia;

    IF nvl(:usado,0) < v_capacidad THEN
        update equipos
        set equ_usado = nvl(:usado,equ_usado), equ_estado = nvl(:estado,equ_estado)
        where equ_licencia = :licencia;
    ELSE
        :error := ''Supera la capacidad máxima'';
    END IF;

    
END;');

