'DECLARE
    v_count     number;
    v_cliente   clientes.cli_id%TYPE := clientes_seq.nextval;
    v_empresa   empresas.emp_id%TYPE := empresas_seq.nextval;
    v_licencia  equipos.equ_licencia%TYPE := generar_licencia();
BEGIN

    -- Comprueba si el correo esta en uso
    select count(''x'') into v_count from clientes where cli_email = :email;

    IF v_count = 0 THEN
        :licencia := v_licencia;

        INSERT INTO CLIENTES (
            CLI_ID, CLI_DNI, CLI_NOMBRE, CLI_CLAVE,
            CLI_ACTIVO, CLI_EMAIL, CLI_TELEFONO,
            CLI_DIRECCION, CLI_TIPO
        ) VALUES (
            v_cliente,
            :dni,
            :nombre,
            toolkit.encriptar(:clave,''AIO987654''),
            ''S'',
            :email,
            :telefono,
            :direccion,
            decode(upper(:tipo),''E'',''E'',''A'')
        );

        INSERT INTO EMPRESAS (EMP_ID, EMP_CLIENTE, EMP_NOMBRE, EMP_CAPACIDAD) VALUES (
            v_empresa,
            v_cliente,
            :empresa,
            :capacidad
        );

        INSERT INTO EQUIPOS (
            EQU_ID, EQU_EMP, EQU_NOMBRE, EQU_IP,
            EQU_UBICACION, EQU_ACTIVO, EQU_ESTADO,
            EQU_LICENCIA, EQU_USADO, EQU_CAPACIDAD
        ) VALUES (
            equipos_seq.nextval,
            v_empresa,
            :equipo,
            :ip,
            :ubicacion,
            ''S'',
            ''CORRECTO'',
            ''S50IBISWSNG9KG0'',
            0,
            :capacidad
        );
    ELSE
        :error := ''Este correo esta en uso'';
    END IF;

    
END;');

